<script setup lang="ts">import {ref} from 'vue';import {api} from '../../api/http';import {useRouter} from 'vue-router';const username=ref('admin'),password=ref(''),error=ref(''),router=useRouter();async function submit(){try{const r=await api.post('/auth/login',{username:username.value,password:password.value});localStorage.setItem('token',r.data.data.token);router.push('/admin/articles')}catch{error.value='登录失败，请检查账户或密码'}}</script><template><section class="card"><h1>管理员登录</h1><form @submit.prevent="submit"><input v-model="username" placeholder="用户名"><input v-model="password" type="password" placeholder="密码"><button>登录</button><p class="error">{{error}}</p></form></section></template>
